-- ========================================================
-- مخطط وقاعدة بيانات منصة الاختبار التجريبي CRMEF (النسخة الشاملة المصفاة)
-- عدد الأسئلة الإجمالي: 1379 سؤالاً
-- ========================================================

create table if not exists public.questions (
    id text primary key,
    cycles jsonb default '["primary"]'::jsonb,
    subject text not null,
    topic text not null,
    question text not null,
    options jsonb not null,
    correct_answer text not null,
    explanation text default '',
    created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

alter table public.questions enable row level security;

create policy "الجميع يمكنهم قراءة الأسئلة" 
on public.questions for select 
using (true);

create policy "السماح بإضافة وتعديل الأسئلة" 
on public.questions for insert 
with check (true);

create policy "السماح بالتعديل" 
on public.questions for update 
using (true);

create policy "السماح بالحذف" 
on public.questions for delete 
using (true);

-- إدراج الأسئلة على دفعات

on conflict (id) do update set
  cycles = excluded.cycles,
  subject = excluded.subject,
  topic = excluded.topic,
  question = excluded.question,
  options = excluded.options,
  correct_answer = excluded.correct_answer,
  explanation = excluded.explanation;

